//! faest batch-FA2 harness (small Galois fields: GF8/GF64) --
//! reference-style mount over the verified src tree.
//!
//! Transcribes the upstream inline test module of
//! code/src/fields/small_fields.rs:314-372 (gf64_test_mul):
//!   - the identity asserts (:329-333): 1*1 == 1, 0*x == 0 (both operand
//!     orders), 1*x == x-feature via lemma_mul64_one_r / zero_r (the
//!     upstream random `anything` value is not reproducible; the twin
//!     covers the identities generically, which is strictly stronger);
//!   - two of the five hardcoded database tuples (:335-359) as full
//!     64-rung model chains (gen_harness_kat.py, model-checked offline);
//!   - the upstream commutativity check (res == res_rev, :368-369) for
//!     one tuple, transcribed as swap-order chains for t1.
//! GF8 has no upstream mul KAT; the GF8 face is covered by the
//! library-side identities (mul8 zero/one/zero-tail lemmas) and the
//! square_bits equivalence theorem plus sample constants below.
//!
//! Consumes verified/src/lib.rs via the #[path] mount; nothing from the
//! src zone is re-copied.

use vstd::prelude::*;

#[path = "../src/lib.rs"]
mod faest;

use faest::fields::small_fields::{
    byte64, gf64_mul_helper, gf64_mul_spec, gf64_mul_bits, gf64_xtime, gf8_mul,
    gf8_square_bits, gf8_mul_spec, gf8_xtime, lemma_mul64_bits_unfold, lemma_mul64_one_r,
    lemma_mul64_zero_r, lemma_mul8_one_r, lemma_mul8_zero_r, gf64_as_bytes, gf64_from_bytes,
    lemma_u64_bytes_eq, lemma_mul64_zero_l,
};

